// Pull the user's text message out of the Messenger webhook payload.
// Skips non-message events (delivery/read receipts), echoes of our own
// messages, and non-text messages (stickers/attachments) for v1.
const body = $json.body || {};
if (body.object !== 'page') { return []; }
const out = [];
for (const entry of (body.entry || [])) {
  for (const ev of (entry.messaging || [])) {
    if (!ev.message) { continue; }
    if (ev.message.is_echo) { continue; }
    const text = ev.message.text;
    if (!text) { continue; }
    out.push({ json: { psid: ev.sender.id, userText: String(text).trim(), pageId: entry.id, mid: ev.message.mid } });
  }
}
return out;

// Parse the model's JSON. On any problem, fail safe -> escalate to a human.
const ctx = $('Setup (KB + Config)').first().json;
const raw = $json.content && $json.content.parts && $json.content.parts[0] ? $json.content.parts[0].text : '';
let clean = String(raw).trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/, '')
  .replace(/```$/, '')
  .trim();
let data;
try { data = JSON.parse(clean); }
catch (e) {
  return [{ json: { psid: ctx.psid, userText: ctx.userText, reply: '', escalate: true, reason: 'Could not parse model output: ' + clean.slice(0, 140) } }];
}
const reply = (data.reply || '').toString().trim();
let escalate = data.escalate === true;
let reason = (data.reason || '').toString().trim();
// Deterministic human-handoff: ALWAYS escalate if the person asks for a person,
// regardless of what the model decided (bulletproofs the Human Agent path).
const HUMAN_RE = /\b(human|real person|real human|talk to (?:a |an )?(?:person|agent|someone|representative)|speak to (?:a |an )?(?:person|agent|someone|representative)|live (?:agent|person)|customer service|support agent|representative)\b/i;
if (HUMAN_RE.test(ctx.userText || '')) { escalate = true; reason = reason || 'User asked to talk to a human'; }
if (!escalate && !reply) { escalate = true; reason = reason || 'Model produced an empty reply'; }
return [{ json: { psid: ctx.psid, userText: ctx.userText, reply, escalate, reason } }];

